code='''from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] != 0 and (ny,nx) not in seen:
                        seen.add((ny,nx))
                        q.append((ny,nx))
            bounds = {}
            for y, x in cells:
                color = grid[y][x]
                if color not in bounds:
                    bounds[color] = [y, y, x, x]
                else:
                    b = bounds[color]
                    b[0] = min(b[0], y); b[1] = max(b[1], y)
                    b[2] = min(b[2], x); b[3] = max(b[3], x)
            colors = sorted(bounds, key=lambda k: (bounds[k][1]-bounds[k][0]+1)*(bounds[k][3]-bounds[k][2]+1), reverse=True)
            remap = dict(zip(colors, reversed(colors)))
            for y, x in cells:
                out[y][x] = remap[grid[y][x]]
    return out
'''
